import { useMemo, useState } from "react";
import { Shuffle, Undo2, Play, Layers, ChevronDown, ChevronUp } from "lucide-react";
import { maladumSets } from "../resource/dataSet/setMeta";
import { allCards, shuffleCards, DREAD_BANDS } from "../util/cardCatalog";
import CardView from "./CardView";

const BAND_CLASS = [
    "from-emerald-500 to-emerald-600",
    "from-yellow-500 to-yellow-600",
    "from-orange-500 to-orange-600",
    "from-rose-500 to-rose-600",
    "from-red-600 to-red-700",
    "from-fuchsia-600 to-purple-700",
];

export default function DeckSimulator() {
    const defaultSets = useMemo(() => new Set(maladumSets.map(s => s.id)), []);
    const [includedSets, setIncludedSets] = useState(defaultSets);
    const [dreadBand, setDreadBand] = useState(0);
    const [deck, setDeck] = useState([]);
    const [drawn, setDrawn] = useState([]); // 뽑힌 순서 (끝이 최신)
    const [configOpen, setConfigOpen] = useState(false);

    const allAvailable = useMemo(() => {
        return allCards().filter(c => includedSets.has(c.setId));
    }, [includedSets]);

    const current = drawn.length > 0 ? drawn[drawn.length - 1] : null;
    const total = allAvailable.length;
    const deckIsDirty = deck.length + drawn.length !== total;

    const handleToggleSet = (setId) => {
        setIncludedSets(prev => {
            const next = new Set(prev);
            if (next.has(setId)) next.delete(setId);
            else next.add(setId);
            return next;
        });
        setDeck([]);
        setDrawn([]);
    };

    const handleReshuffle = () => {
        setDeck(shuffleCards(allAvailable));
        setDrawn([]);
    };

    const handleDraw = () => {
        if (allAvailable.length === 0) return;
        if (deck.length === 0 && drawn.length === 0) {
            // 최초 뽑기: 셔플 후 1장
            const shuffled = shuffleCards(allAvailable);
            setDeck(shuffled.slice(1));
            setDrawn([shuffled[0]]);
            return;
        }
        if (deck.length === 0) {
            // 덱 소진 — 더 이상 뽑을 수 없음 (명시적 재셔플 유도)
            return;
        }
        const [next, ...rest] = deck;
        setDeck(rest);
        setDrawn(prev => [...prev, next]);
    };

    const handleUndo = () => {
        if (drawn.length === 0) return;
        const last = drawn[drawn.length - 1];
        setDrawn(prev => prev.slice(0, -1));
        setDeck(prev => [last, ...prev]);
    };

    const canDraw = allAvailable.length > 0 && (deck.length > 0 || drawn.length === 0);
    const empty = allAvailable.length === 0;
    const deckEmpty = drawn.length > 0 && deck.length === 0;

    const setConfigPanel = (
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
            <div className="mb-3 flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                <Layers className="w-3.5 h-3.5" /> 덱 구성
            </div>
            <div className="flex flex-col gap-1.5">
                {maladumSets.map(s => {
                    const on = includedSets.has(s.id);
                    return (
                        <button
                            key={s.id}
                            onClick={() => handleToggleSet(s.id)}
                            className={`flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-left transition-colors ${
                                on
                                    ? "bg-gradient-to-r " + s.accent + " text-white shadow-md"
                                    : "bg-white/[0.02] text-slate-400 hover:bg-white/[0.06]"
                            }`}
                        >
                            <span className="flex items-center gap-2 min-w-0">
                                <span className={`shrink-0 w-3.5 h-3.5 rounded ring-1 ${on ? "bg-white/90 ring-white/80" : "bg-transparent ring-white/30"}`}>
                                    {on && <span className="block w-full h-full rounded bg-rose-500/90" />}
                                </span>
                                <span className="min-w-0">
                                    <span className="block text-sm font-semibold truncate">{s.name_ko}</span>
                                    <span className="block text-[10px] opacity-70 truncate">{s.name}</span>
                                </span>
                            </span>
                            <span className={`text-xs tabular-nums ${on ? "text-white" : "text-slate-500"}`}>
                                {s.data.cards.length}
                            </span>
                        </button>
                    );
                })}
            </div>
            <div className="mt-3 pt-3 border-t border-white/5 text-xs text-slate-400 flex items-center justify-between">
                <span>총 포함</span>
                <span className="text-white font-semibold tabular-nums">{total}장</span>
            </div>
        </div>
    );

    return (
        <div className="flex flex-col gap-4 sm:grid sm:grid-cols-12 sm:gap-5">
            {/* 모바일 전용: 설정 토글 */}
            <div className="sm:hidden">
                <button
                    onClick={() => setConfigOpen(o => !o)}
                    className="flex w-full items-center justify-between rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5"
                >
                    <span className="flex items-center gap-2 text-sm font-semibold text-rose-200">
                        <Layers className="w-4 h-4" />
                        덱 구성 ({includedSets.size}세트 · {total}장)
                    </span>
                    {configOpen
                        ? <ChevronUp className="w-4 h-4 text-slate-400" />
                        : <ChevronDown className="w-4 h-4 text-slate-400" />}
                </button>
                {configOpen && <div className="mt-3">{setConfigPanel}</div>}
            </div>

            {/* 좌측: 설정 (sm 이상) */}
            <aside className="hidden sm:block sm:col-span-3">
                {setConfigPanel}
            </aside>

            {/* 중앙: 공포 단계 + 조작 + 현재 카드 + 이력 */}
            <section className="sm:col-span-9 flex flex-col gap-4">
                {/* 공포 단계 세그먼트 */}
                <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3">
                    <div className="mb-2 flex items-center justify-between gap-2">
                        <span className="text-xs tracking-widest uppercase text-rose-300/80">
                            공포 단계 (Dread)
                        </span>
                        <span className="text-sm text-white font-semibold">
                            {DREAD_BANDS[dreadBand].ko}
                            <span className="ml-1 text-xs text-slate-500">({DREAD_BANDS[dreadBand].en})</span>
                        </span>
                    </div>
                    <div className="grid grid-cols-6 gap-1">
                        {DREAD_BANDS.map(d => (
                            <button
                                key={d.id}
                                onClick={() => setDreadBand(d.id)}
                                className={`rounded-md px-1 py-1.5 text-[11px] sm:text-xs font-medium transition-all ${
                                    d.id === dreadBand
                                        ? `bg-gradient-to-r ${BAND_CLASS[d.id]} text-white shadow-md`
                                        : "bg-white/[0.03] text-slate-400 hover:bg-white/[0.08]"
                                }`}
                            >
                                <div className="truncate">{d.ko}</div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* 조작 바 */}
                <div className="flex items-stretch gap-2">
                    <button
                        onClick={handleDraw}
                        disabled={!canDraw}
                        className="flex-1 inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-rose-500 to-fuchsia-500 px-4 py-3 text-sm font-bold text-white shadow-lg shadow-rose-500/20 transition-opacity hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                        <Play className="w-4 h-4" />
                        {drawn.length === 0 ? "셔플 & 뽑기" : "카드 뽑기"}
                    </button>
                    <button
                        onClick={handleUndo}
                        disabled={drawn.length === 0}
                        title="되돌리기"
                        className="inline-flex items-center justify-center rounded-xl bg-white/[0.04] px-3 py-3 text-slate-300 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                    >
                        <Undo2 className="w-4 h-4" />
                    </button>
                    <button
                        onClick={handleReshuffle}
                        disabled={empty}
                        title="다시 섞기"
                        className="inline-flex items-center justify-center rounded-xl bg-white/[0.04] px-3 py-3 text-slate-300 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                    >
                        <Shuffle className="w-4 h-4" />
                    </button>
                </div>

                {/* 덱 상태 */}
                <div className="flex items-center justify-between rounded-xl border border-white/10 bg-white/[0.02] px-4 py-2 text-xs text-slate-400">
                    <div className="flex items-center gap-3">
                        <span>덱 남음 <span className="text-white font-semibold tabular-nums">{deck.length}</span></span>
                        <span className="text-slate-700">·</span>
                        <span>뽑힘 <span className="text-white font-semibold tabular-nums">{drawn.length}</span></span>
                        <span className="text-slate-700">·</span>
                        <span>전체 <span className="text-slate-300 tabular-nums">{total}</span></span>
                    </div>
                    {deckEmpty && (
                        <span className="text-[11px] text-amber-300/90">덱 소진 — 다시 섞기 눌러주세요</span>
                    )}
                </div>

                {/* 현재 카드 */}
                {current ? (
                    <div>
                        <CardView card={current} highlightDread={dreadBand} />
                    </div>
                ) : (
                    <div className="flex h-[40vh] flex-col items-center justify-center rounded-2xl border border-dashed border-white/10 bg-white/[0.02] text-center p-8">
                        <Shuffle className="w-8 h-8 text-slate-600 mb-3" />
                        <p className="text-sm text-slate-400">
                            {empty
                                ? "덱 구성에서 세트를 하나 이상 선택하세요"
                                : '"셔플 & 뽑기"를 눌러 시작하세요'}
                        </p>
                        {!empty && (
                            <p className="mt-2 text-xs text-slate-600">
                                공포 단계에 해당하는 섹션이 강조되어 표시됩니다
                            </p>
                        )}
                    </div>
                )}

                {/* 이력 썸네일 */}
                {drawn.length > 1 && (
                    <div>
                        <div className="text-xs tracking-widest uppercase text-slate-500 mb-2">
                            이력 (최근 → 과거)
                        </div>
                        <div className="flex gap-2 overflow-x-auto pb-2">
                            {drawn.slice(0, -1).slice(-10).reverse().map((c, i) => (
                                <div
                                    key={`${c.setId}-${c.globalId}-${drawn.length - 2 - i}`}
                                    className="shrink-0 rounded-lg border border-white/10 bg-white/[0.02] px-3 py-2 min-w-[140px]"
                                >
                                    <div className="text-[10px] font-mono text-slate-500">
                                        #{String(c.globalId).padStart(3, "0")}
                                    </div>
                                    <div className="text-xs font-semibold text-white truncate">
                                        {c.card_ko}
                                    </div>
                                    <div className="text-[10px] text-slate-500 truncate">
                                        {c.setName_ko}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </section>
        </div>
    );
}
