import { Component } from "react";
import { BookOpen, Dices } from "lucide-react";
import withNavigate from "../../utils/withNavigate";
import CardBrowser from "../component/CardBrowser";
import DeckSimulator from "../component/DeckSimulator";

const TABS = [
    { id: "browser", label: "카드 브라우저", icon: BookOpen },
    { id: "simulator", label: "덱 시뮬레이터", icon: Dices },
];

class MaladumManager extends Component {

    state = {
        tab: "browser",
    }

    handler = {
        selectTab: (id) => this.setState({ tab: id }),
    }

    renderTabContent() {
        switch (this.state.tab) {
            case "browser":
                return <CardBrowser />;
            case "simulator":
                return <DeckSimulator />;
            default:
                return null;
        }
    }

    render() {
        return (
            <div className="relative overflow-hidden bg-[#0a0118] min-h-[80vh]">
                <div className="absolute inset-0 overflow-hidden pointer-events-none">
                    <div className="absolute -top-32 -left-24 h-96 w-96 rounded-full bg-rose-500/15 blur-[120px]"/>
                    <div className="absolute top-1/3 -right-24 h-[28rem] w-[28rem] rounded-full bg-fuchsia-600/15 blur-[130px]"/>
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_1px_1px,rgba(255,255,255,0.06)_1px,transparent_0)] [background-size:28px_28px]"/>
                </div>

                <div className="container relative px-3 py-6 mx-auto sm:px-6 sm:py-8">
                    <header className="flex flex-col items-center mb-6 text-center sm:mb-8">
                        <p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.3em] text-rose-400/80 sm:text-xs">
                            Maladum
                        </p>
                        <h1 className="text-2xl font-bold text-white sm:text-4xl">
                            말라둠{" "}
                            <span className="text-transparent bg-gradient-to-r from-rose-300 to-fuchsia-300 bg-clip-text">
                                이벤트 덱
                            </span>
                        </h1>
                        <p className="mt-3 max-w-xl text-xs text-slate-400 sm:text-sm">
                            엔베론의 던전 · 에일과 모험 · 망각의 아귀 — 세 세트의 이벤트 카드를 탐색하고,
                            공포 단계별 효과를 확인하세요.
                        </p>

                        <nav className="mt-5 inline-flex rounded-xl bg-white/[0.03] p-1 ring-1 ring-white/10 sm:mt-6">
                            {TABS.map(t => {
                                const Icon = t.icon;
                                const isActive = t.id === this.state.tab;
                                return (
                                    <button
                                        key={t.id}
                                        disabled={t.disabled}
                                        onClick={() => this.handler.selectTab(t.id)}
                                        className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors sm:gap-2 sm:px-4 sm:py-2 sm:text-sm ${
                                            isActive
                                                ? "bg-gradient-to-r from-rose-500 to-fuchsia-500 text-white shadow-md"
                                                : t.disabled
                                                    ? "text-slate-600 cursor-not-allowed"
                                                    : "text-slate-300 hover:bg-white/5"
                                        }`}
                                    >
                                        <Icon className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                                        {t.label}
                                        {t.disabled && (
                                            <span className="ml-1 rounded bg-white/5 px-1.5 py-0.5 text-[9px] text-slate-500">
                                                준비 중
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </nav>
                    </header>

                    <main>
                        {this.renderTabContent()}
                    </main>
                </div>
            </div>
        );
    }
}

export default withNavigate(MaladumManager);
