import { useState } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";
import CardIcon from "./CardIcon";
import { dreadRange } from "../util/cardCatalog";

const DREAD_BAND_COLOR = [
    "from-emerald-500/20 to-emerald-700/5",   // DISQUIET
    "from-yellow-500/20 to-yellow-700/5",     // DISTRESS
    "from-orange-500/20 to-orange-700/5",     // DISMAY
    "from-rose-500/20 to-rose-700/5",         // DESPERATION
    "from-red-600/20 to-red-800/5",           // DISASTER
    "from-fuchsia-600/20 to-purple-800/5",    // DOOM
];

// "... [fire] ..." 같은 토큰을 CardIcon으로 치환
const TOKEN_RE = /\[([a-zA-Z0-9_-]+)\]/g;
function renderWithIcons(text) {
    if (!text) return null;
    const parts = [];
    let lastIndex = 0;
    let m;
    let key = 0;
    while ((m = TOKEN_RE.exec(text)) !== null) {
        if (m.index > lastIndex) {
            parts.push(text.slice(lastIndex, m.index));
        }
        parts.push(<CardIcon key={`i${key++}`} name={m[1]} size={16} className="mx-0.5" />);
        lastIndex = m.index + m[0].length;
    }
    if (lastIndex < text.length) {
        parts.push(text.slice(lastIndex));
    }
    return parts;
}

function SectionBlock({ section, highlightDread }) {
    const range = dreadRange(section.label);
    const accent = range ? DREAD_BAND_COLOR[range.end] : "from-slate-500/10 to-slate-700/5";
    const isHighlightMode = typeof highlightDread === "number";
    const isActive = isHighlightMode && range &&
        highlightDread >= range.start && highlightDread <= range.end;
    const dimmed = isHighlightMode && !isActive;
    return (
        <div className={`rounded-lg bg-gradient-to-br ${accent} ring-1 p-4 transition-opacity ${
            isActive
                ? "ring-rose-400/60 shadow-lg shadow-rose-500/20"
                : "ring-white/10"
        } ${dimmed ? "opacity-40" : ""}`}>
            <div className="flex items-center justify-between gap-3 mb-2">
                <div>
                    <span className="text-[11px] font-mono tracking-widest text-slate-300/70 uppercase">
                        {section.label}
                    </span>
                    {section.label_ko && (
                        <div className="text-sm font-semibold text-white">
                            {section.label_ko}
                        </div>
                    )}
                </div>
                {isActive && (
                    <span className="shrink-0 rounded-full bg-rose-500/30 px-2 py-0.5 text-[10px] font-semibold text-rose-100 ring-1 ring-rose-400/50">
                        현재
                    </span>
                )}
            </div>
            <p className="whitespace-pre-wrap text-sm leading-relaxed text-slate-100">
                {renderWithIcons(section.text_ko)}
            </p>
        </div>
    );
}

function OriginalSections({ sections }) {
    const [open, setOpen] = useState(false);
    if (!sections || !sections.length) return null;
    return (
        <div className="px-4 pb-4 sm:px-6">
            <button
                onClick={() => setOpen(o => !o)}
                className="flex w-full items-center justify-between gap-2 rounded-lg border border-white/10 bg-white/[0.02] px-3 py-2 text-left text-xs font-semibold text-slate-300 hover:bg-white/[0.04]"
            >
                <span className="tracking-wider uppercase text-rose-300/70">원문 보기 (아이콘 포함)</span>
                {open
                    ? <ChevronUp className="w-3.5 h-3.5 text-slate-400" />
                    : <ChevronDown className="w-3.5 h-3.5 text-slate-400" />}
            </button>
            {open && (
                <div className="mt-2 space-y-2">
                    {sections.map((s, i) => (
                        <div key={i} className="rounded-lg bg-white/[0.02] ring-1 ring-white/5 p-3">
                            <div className="mb-1 text-[10px] font-mono tracking-widest text-slate-400 uppercase">
                                {s.label}
                            </div>
                            <p className="whitespace-pre-wrap text-[13px] leading-relaxed text-slate-300">
                                {renderWithIcons(s.text)}
                            </p>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

export default function CardView({ card, onClose, highlightDread }) {
    if (!card) return null;
    const leftIcons = card.footer?.left || [];
    const rightIcons = card.footer?.right || [];

    return (
        <div className="relative flex flex-col gap-4 rounded-2xl border border-white/10 bg-gradient-to-br from-[#140414] via-[#0d0416] to-[#080015] shadow-2xl sm:h-full sm:overflow-hidden">
            {/* 헤더 */}
            <div className="relative px-4 pt-4 pb-3 border-b border-white/10 sm:px-6 sm:pt-5 sm:pb-4">
                <div className="flex items-start justify-between gap-3 sm:gap-4">
                    <div className="min-w-0">
                        <div className="text-[10px] font-mono tracking-widest text-rose-400/80 uppercase mb-1">
                            #{String(card.globalId || card.id).padStart(3, "0")} · {card.setName_ko}
                        </div>
                        <h2 className="text-xl font-bold text-white break-keep sm:text-2xl">
                            {card.card_ko}
                        </h2>
                        <div className="mt-1 text-xs text-slate-400">
                            {card.card}
                        </div>
                    </div>
                    {onClose && (
                        <button
                            onClick={onClose}
                            className="shrink-0 rounded-lg px-2.5 py-1.5 text-xs text-slate-300 ring-1 ring-white/10 hover:bg-white/5"
                        >
                            닫기
                        </button>
                    )}
                </div>

                <div className="flex flex-wrap items-center gap-2 mt-3">
                    {card.type_ko && (
                        <span className="inline-flex items-center rounded-full bg-white/5 px-2.5 py-1 text-xs font-medium text-rose-200 ring-1 ring-rose-400/30">
                            {card.type_ko}
                        </span>
                    )}
                    {(card.tags || []).map(tag => (
                        <span
                            key={tag}
                            className="inline-flex items-center rounded-full bg-white/[0.03] px-2 py-0.5 text-[10px] font-medium text-slate-400 ring-1 ring-white/10"
                        >
                            {tag}
                        </span>
                    ))}
                </div>
            </div>

            {/* 섹션 리스트 */}
            <div className="sm:flex-1 sm:min-h-0 sm:overflow-y-auto">
                <div className="px-4 pb-2 space-y-3 sm:px-6">
                    {(card.sections || []).map((s, i) => (
                        <SectionBlock key={i} section={s} highlightDread={highlightDread} />
                    ))}
                </div>
                <OriginalSections sections={card.sectionsEn} />
            </div>

            {/* 하단 아이콘 */}
            {(leftIcons.length > 0 || rightIcons.length > 0) && (
                <div className="flex items-center justify-between gap-2 px-4 py-3 border-t border-white/10 bg-white/[0.02] sm:px-6">
                    <div className="flex items-center gap-2">
                        {leftIcons.map((t, i) => (
                            <CardIcon key={`l${i}`} name={t.name} size={22} />
                        ))}
                    </div>
                    <div className="flex items-center gap-2">
                        {rightIcons.map((t, i) => (
                            <CardIcon key={`r${i}`} name={t.name} size={22} />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}
