import { maladumSets } from "../resource/dataSet/setMeta";

// 공포 단계 라벨을 "밴드 번호"로 매핑. 라벨 내부에 어떤 공포명이 포함되는지로 범위를 추정한다.
// Distress < Dismay < Desperation < Doom
const DREAD_ORDER = ["DISQUIET", "DISTRESS", "DISMAY", "DESPERATION", "DISASTER", "DOOM"];

// 같은 세트 안에 동일한 영문명 카드가 여러 장(예: "Eldritch Tentacle" x3) 있을 수 있으므로,
// 영문 섹션을 매칭할 때는 "N번째 등장" 기준으로 순서대로 바인딩한다.
function enrichSectionsWithEn(koCards, enCards) {
    if (!enCards || !enCards.length) return koCards;
    const buckets = new Map(); // name → 영문 카드 index 리스트
    for (let i = 0; i < enCards.length; i++) {
        const name = enCards[i].card;
        if (!buckets.has(name)) buckets.set(name, []);
        buckets.get(name).push(i);
    }
    const used = {};
    return koCards.map(k => {
        const name = k.card;
        const indices = buckets.get(name) || [];
        const n = used[name] || 0;
        if (n < indices.length) {
            used[name] = n + 1;
            return { ...k, sectionsEn: enCards[indices[n]].sections || [] };
        }
        return k;
    });
}

export function allCards() {
    return maladumSets.flatMap(set => {
        const enCards = (set.dataEn && set.dataEn.cards) || [];
        const enriched = enrichSectionsWithEn(set.data.cards, enCards);
        return enriched.map(card => ({
            ...card,
            setId: set.id,
            setName_ko: set.name_ko,
        }));
    });
}

// 타입 집합 (중복 제거, 정렬)
export function allTypes(cards) {
    const set = new Set();
    for (const c of cards) {
        for (const t of String(c.type || "").split(/[+/,]/)) {
            const trimmed = t.trim();
            if (trimmed) set.add(trimmed);
        }
    }
    return [...set].sort();
}

// 간단 검색: 한글 제목, 영문 제목, 본문
// 검색어가 있으면 세트 필터는 무시하고 전체 세트에서 검색한다
// (영문명은 보통 "어느 세트인지 모를 때" 치는 경우가 많으므로)
export function filterCards(cards, { setId, type, query }) {
    const q = (query || "").trim().toLowerCase();
    const searching = q.length > 0;
    return cards.filter(c => {
        if (!searching && setId && c.setId !== setId) return false;
        if (type) {
            const types = String(c.type || "").split(/[+/,]/).map(t => t.trim());
            if (!types.includes(type)) return false;
        }
        if (searching) {
            const hay = [
                c.card,
                c.card_ko,
                c.type,
                c.type_ko,
                ...(c.sections || []).map(s => s.text_ko || ""),
                ...(c.sectionsEn || []).map(s => s.text || ""),
            ].join(" ").toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

// 라벨에 포함된 공포 범위 (시작, 끝 인덱스). 없으면 null.
export function dreadRange(label) {
    const parts = String(label || "").toUpperCase().split("-").map(s => s.trim());
    const indices = parts
        .map(p => DREAD_ORDER.indexOf(p))
        .filter(i => i >= 0);
    if (!indices.length) return null;
    return { start: Math.min(...indices), end: Math.max(...indices) };
}

export const DREAD_BANDS = [
    { id: 0, en: "DISQUIET", ko: "불안" },
    { id: 1, en: "DISTRESS", ko: "동요" },
    { id: 2, en: "DISMAY", ko: "경악" },
    { id: 3, en: "DESPERATION", ko: "절망" },
    { id: 4, en: "DISASTER", ko: "참사" },
    { id: 5, en: "DOOM", ko: "파멸" },
];

// Fisher-Yates 셔플 (비파괴)
export function shuffleCards(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}
